"""ROS2 토픽 구독 카메라 (Jetson/로봇에서 realsense2_camera 노드가 토픽을 쏠 때).

color + (color에 정렬된)depth Image 토픽을 구독해 최신 프레임을 보관하고,
read() 로 (color_bgr, depth_uint16) 를 반환한다. RealSenseCamera/WebcamCamera 와 동일 인터페이스.

depth 는 16UC1(mm) 가정. 노드의 depth_scale 을 0.001(mm->m)로 두면 거리 계산이 맞는다.
정확한 거리를 위해 depth 는 color 에 정렬된 토픽
(/camera/.../aligned_depth_to_color/image_raw)을 쓰는 것을 권장.
"""

import threading
import time

import cv2
import numpy as np
from rclpy.executors import SingleThreadedExecutor
from sensor_msgs.msg import Image


class RosTopicCamera:
    def __init__(self, node, color_topic, depth_topic):
        self.node = node
        self.color_topic = color_topic
        self.depth_topic = depth_topic
        self._color = None
        self._depth = None
        self._seq = 0            # color 프레임 수신 카운터
        self._last_read_seq = -1
        self._lock = threading.Lock()
        self._executor = None

    def start(self):
        self.node.create_subscription(Image, self.color_topic, self._on_color, 10)
        self.node.create_subscription(Image, self.depth_topic, self._on_depth, 10)
        # 구독 콜백을 받기 위해 백그라운드 스레드에서 노드 spin
        self._executor = SingleThreadedExecutor()
        self._executor.add_node(self.node)
        threading.Thread(target=self._executor.spin, daemon=True).start()
        self.node.get_logger().info(
            f'ROS 토픽 구독: color={self.color_topic}, depth={self.depth_topic}')
        return None

    def _on_color(self, msg):
        if msg.encoding not in ('rgb8', 'bgr8'):
            return
        img = np.frombuffer(msg.data, np.uint8).reshape(msg.height, msg.width, 3)
        if msg.encoding == 'rgb8':
            img = img[:, :, ::-1]  # RGB -> BGR
        img = np.ascontiguousarray(img)
        with self._lock:
            self._color = img
            self._seq += 1

    def _on_depth(self, msg):
        if msg.encoding not in ('16UC1', 'mono16'):
            return
        depth = np.frombuffer(msg.data, np.uint16).reshape(msg.height, msg.width)
        with self._lock:
            self._depth = depth

    def read(self):
        with self._lock:
            # 새 color 프레임이 없으면 (None, None) -> 노드는 스킵
            if self._color is None or self._seq == self._last_read_seq:
                color, depth = None, None
            else:
                self._last_read_seq = self._seq
                color = self._color.copy()
                depth = None if self._depth is None else self._depth.copy()
        if color is None:
            time.sleep(0.005)  # 새 프레임 대기(busy loop 방지)
            return color, depth
        # depth 해상도가 color 와 다르면 color 크기에 맞춰 리사이즈(인덱싱 일치용)
        # (비정렬 depth 는 FOV 가 정확히 안 맞으므로 거리값은 근사 — 정확하려면 카메라
        #  노드를 align_depth.enable:=true 로 띄워 aligned 토픽을 쓸 것)
        if depth is not None and depth.shape[:2] != color.shape[:2]:
            h, w = color.shape[:2]
            depth = cv2.resize(depth, (w, h), interpolation=cv2.INTER_NEAREST)
        return color, depth

    def stop(self):
        if self._executor is not None:
            self._executor.shutdown()
            self._executor = None
